import React from "react";
import { Link } from "react-router-dom";

export default function Navbar() {
  return (
    <header className="bg-white shadow p-4 flex justify-between items-center">
      <h1 className="text-xl font-bold text-indigo-700">Sikkim Monasteries</h1>
      <nav className="space-x-4">
        <Link to="/" className="hover:text-indigo-600">Home</Link>
        <Link to="/monasteries" className="hover:text-indigo-600">Monasteries</Link>
        <Link to="/archive" className="hover:text-indigo-600">Archive</Link>
        <Link to="/virtual" className="hover:text-indigo-600">Virtual</Link>
        <Link to="/events" className="hover:text-indigo-600">Events</Link>
        <Link to="/research" className="hover:text-indigo-600">Research</Link>
        <Link to="/about" className="hover:text-indigo-600">About</Link>
        <Link to="/contact" className="hover:text-indigo-600">Contact</Link>
      </nav>
    </header>
  );
}
